// The AI Gateway model catalog for the match-setup picker, loaded from the baked
// public/assets/models.json (generated by src/tools/fetch-models.ts). Grouped by
// provider so the modal can offer provider → model selection rather than one flat
// list of ~200 combos. Loaded synchronously at import (small JSON, offline).
import { readFileSync } from 'node:fs';
import { asset } from '../assets.ts';

export interface ModelInfo {
  id: string; // "provider/model" gateway slug
  name: string; // display name
}
export interface ProviderInfo {
  slug: string;
  name: string; // display label
  models: ModelInfo[];
}

const catalog: { providers: ProviderInfo[] } = JSON.parse(readFileSync(asset('models.json'), 'utf8'));

// Providers hidden from the picker because they don't actually play through the
// gateway right now (verified via src/tools/model-probe.ts): `arcee-ai` is gated
// behind a separate access profile, `meituan` reports "Unsupported model", and
// `sakana` hangs past the request timeout. Drop a slug from this set once it works.
// Direct lookups (modelsFor / modelName) still resolve these, so the probe can
// re-test them by name; only the listed/selectable set excludes them.
const UNSUPPORTED = new Set(['arcee-ai', 'meituan', 'sakana']);

// Selectable providers (picker + probe sweep) — excludes the unsupported ones.
export function providers(): ProviderInfo[] {
  return catalog.providers.filter((p) => !UNSUPPORTED.has(p.slug));
}
export function modelsFor(slug: string): ModelInfo[] {
  return catalog.providers.find((p) => p.slug === slug)?.models ?? [];
}
export function providerName(slug: string): string {
  return catalog.providers.find((p) => p.slug === slug)?.name ?? slug;
}
export function modelName(id: string): string {
  for (const p of catalog.providers) {
    const m = p.models.find((mm) => mm.id === id);
    if (m) return m.name;
  }
  return id;
}
